 const minX=left-startX,maxX=end-startX;
 const smooth=t=>t*t*(3-2*t);
 // Sample a continuous curve so position, sway and fade share one animation clock.
 // Horizontal movement eases in/out; ascent gently slows as the bubble dissipates.
 const frames=Array.from({length:49},(_,index)=>{
  const t=index/48,progress=1-Math.pow(1-t,1.45);
  const wave=Math.sin(Math.PI*progress)*Math.sin(Math.PI*progress*1.35)*sway*direction;
  const x=Math.max(minX,Math.min(maxX,drift*smooth(progress)+wave));
  const y=-rise*progress;
  const scale=lucky?(t<.1?.82+.18*smooth(t/.1):1):(t<.2?.94+.06*smooth(t/.2):1);
  const tilt=direction*1.4*Math.sin(Math.PI*progress);
  const fadeIn=lucky?.055:.12,fadeOut=lucky?.82:.65;
  const opacity=t<fadeIn?smooth(t/fadeIn):t>fadeOut?1-smooth((t-fadeOut)/(1-fadeOut)):1;
  return {offset:t,opacity,transform:reduce?'translate(-50%,0)':
   'translate(calc(-50% + '+x+'px),'+y+'px) rotate('+tilt+'deg) scale('+scale+')'};
 });
